export default class AddressUpdated {
    constructor(details) {
        this.transaction = details;
    }

    toSegment() {
        return {
            event: 'Address Updated',
            properties: {
              checkout_id: this.transaction.cart_id,
              order_id: this.transaction.order_id,
              cart_id: this.transaction.cart_id,
              customer: {
                id: this.transaction.customer?.id,
                name: this.transaction.customer?.first_name + ' ' + this.transaction.customer?.last_name,
                mobile: this.transaction.customer?.mobile,
                email: this.transaction.customer?.email,
                gender: this.transaction.customer?.gender,
              },
              address : {
                local : this.transaction.address?.local,
                street: this.transaction.address?.street,
                postal_code: this.transaction.address?.postal_code,
                short_address: this.transaction.address?.short_address,
                region: {
                  id: this.transaction.address?.region?.id,
                  name: this.transaction.address?.region?.name
                },
                city: {
                  id: this.transaction.address?.city?.id,
                  name: this.transaction.address?.city?.name
                },
                country: {
                  id: this.transaction.address?.country?.id,
                  name: this.transaction.address?.country?.name
                },
                district: {
                  id: this.transaction.address?.district?.id,
                  name: this.transaction.address?.district?.name
                }
              }
            }
        };
    }
}

